 List<CorrectionHistoryEntry> getCorrectionHistory(){return correctionHistory;}public void setCorrectionHistory(List<CorrectionHistoryEntry> v){correctionHistory=v;}public String getCreatedBy(){return createdBy;}public void setCreatedBy(String v){createdBy=v;}public String getUpdatedBy(){return updatedBy;}public void setUpdatedBy(String v){updatedBy=v;}public long getVersion(){return version;}public void setVersion(long v){version=v;}public Instant getCreatedAt(){return createdAt;}public void setCreatedAt(Instant v){createdAt=v;}public Instant getUpdatedAt(){return updatedAt;}public void setUpdatedAt(Instant v){updatedAt=v;}
